mapper.update:
UPDATE dodo_theme_top_list
title = #{title}, sort_order = #{sortOrder}, is_prod = #{isProd}, association_priority = #{associationPriority}, recommend_position = #{recommendPosition}, top_url = #{topUrl}, background_image = #{backgroundImage}, background_color = #{backgroundColor}, goods_count = #{goodsCount},
