UPDATE dodo_theme_top_list SET
title = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.title}
    ELSE title END,
sort_order = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.sortOrder}
    ELSE sort_order END,
is_prod = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.isProd}
    ELSE is_prod END,
association_priority = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.associationPriority}
    ELSE association_priority END,
recommend_position = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.recommendPosition}
    ELSE recommend_position END,
top_url = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.topUrl}
    ELSE top_url END,
background_image = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.backgroundImage}
    ELSE background_image END,
background_color = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.backgroundColor}
    ELSE background_color END,
goods_count = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.goodsCount}
    ELSE goods_count END
WHERE (id = #{item.id} AND store_id = #{item.storeId})
